<?php
namespace Modules\BankingCheque\Http\Controllers;
use Illuminate\Routing\Controller; use Illuminate\Http\Request; use Modules\BankingCheque\Entities\ChequeBook; use Modules\BankingCheque\Services\ChequeBookService;
class ChequeBookController extends Controller { public function index(){ $books=ChequeBook::latest()->paginate(25); return view('bankingcheque::cheque_books.index', compact('books')); } public function create(){ return view('bankingcheque::cheque_books.create'); } public function store(Request $r, ChequeBookService $s){ $s->issue($r->all()+['status'=>'issued','issue_date'=>now()->toDateString()]); return redirect()->route('banking.cheques.books.index')->with('status','Cheque book issued'); } public function show(ChequeBook $book){ return view('bankingcheque::cheque_books.show',compact('book')); } public function edit(ChequeBook $book){ return view('bankingcheque::cheque_books.edit',compact('book')); } public function update(Request $r, ChequeBook $book){ $book->update($r->all()); return back()->with('status','Updated'); } public function destroy(ChequeBook $book){ $book->update(['status'=>'cancelled']); return back(); } }
